      const raw = row.jev_raw_json ? JSON.parse(row.jev_raw_json) : null;
      const arms = calculateArms({ ...request, facts }, raw, table, thresholds);
      const withJson = JSON.stringify({ ...arms.withJev, traits: Object.entries(arms.withTraits).map(([name25, value]) => ({ name: name25, ...value })) });
      const withoutJson = JSON.stringify({ ...arms.withoutJev, traits: Object.entries(arms.estimated).map(([name25, value]) => ({ name: name25, ...value })) });
