      registry2.db.prepare("INSERT INTO replays (recommendation_id,policy_version,table_hash,with_jev_json,without_jev_json,with_jev_valid,created_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT (recommendation_id,policy_version,table_hash) DO UPDATE SET with_jev_json=excluded.with_jev_json,without_jev_json=excluded.without_jev_json,with_jev_valid=excluded.with_jev_valid,created_at=excluded.created_at").run(row.recommendation_id, policyVersion, tableHash, withJson, withoutJson, Number(withValid), now.toISOString());
      counts.recommendations++;
      if (comparable(withJson) !== comparable(row.with_jev_json)) counts.withJevChanged++;
      if (comparable(withoutJson) !== comparable(row.without_jev_json)) counts.withoutJevChanged++;
      if (row.jev_status === "used" && row.jev_questions_version !== JEV_QUESTIONS_VERSION) counts.withJevInvalidatedByQuestions++;
