    for (const item of pendingPairs(registry2, tableHash)) {
      const order = flip() ? "ba" : "ab";
      const a = order[0] === "a" ? item.selectionA : item.selectionB;
      const b = order[1] === "a" ? item.selectionA : item.selectionB;
      const facts = JSON.parse(item.input_json).facts;
      write(`
Resumen: ${item.summary ?? "(sin resumen: excluido, marcado o podado)"}
Hechos: ${JSON.stringify(facts)}
A: ${a.model} ${a.effort}
B: ${b.model} ${b.effort}
Despachado: ${item.dispatched_model} ${item.dispatched_effort}; veredicto: ${item.verdict}; rondas de correcci\xF3n: ${item.correction_rounds}
`);
      while (true) {
        write("Elige a, b, e (empate), s (saltar) o q (salir): ");
        const answer = await input3.next();
        const choice2 = answer.done ? "q" : answer.value.trim().toLowerCase();
        if (choice2 === "q") {
          write(`
adjudicados: ${adjudicated}; pendientes: ${pendingPairs(registry2, tableHash).length}
`);
          return;
        }
        if (choice2 === "s") break;
        if (choice2 !== "a" && choice2 !== "b" && choice2 !== "e") continue;
        const winner = choice2 === "e" ? "tie" : order[choice2 === "a" ? 0 : 1];
        registry2.db.prepare("INSERT OR IGNORE INTO adjudications (recommendation_id,pair,selection_a_json,selection_b_json,winner,source,rule,shown_order,created_at) VALUES (?,?,?,?,?,?,?,?,?)").run(item.recommendation_id, item.pair, selectionJson(item.selectionA), selectionJson(item.selectionB), winner, "blind", null, order, clock().toISOString());
        adjudicated++;
        break;
      }
    }
    write(`
adjudicados: ${adjudicated}; pendientes: ${pendingPairs(registry2, tableHash).length}
`);
